var e={"feedback.title":`フィードバックを送信`,"feedback.description":`バグ、アイデア、わかりにくい点はありますか？まず、あなたの Harness が自分で回答または対応できるかを確認します。できない場合は、すべてのメッセージに目を通している Harness Maxxing チームにメッセージが送られます。`,"feedback.checking":`Harness がメッセージを確認しています…`,"feedback.reply.answerTitle":`Harness から回答があります`,"feedback.reply.selfTitle":`Harness がここで対応できます`,"feedback.reply.notSent":`チームには何も送信されていません。`,"feedback.reply.prompt":`セッション用に準備されたリクエストを見る`,"feedback.reply.open":`セッションを開く`,"feedback.reply.edit":`メッセージを編集`,"feedback.reply.force":`それでもチームに送信`,"feedback.type.bug":`バグ`,"feedback.type.idea":`アイデア`,"feedback.type.other":`その他`,"feedback.message":`メッセージ`,"feedback.placeholder.bug":`何が起きたか、何を期待していたか、どうすれば再現できるかを入力してください…`,"feedback.placeholder.idea":`Harness Maxxing にどんなことをしてほしいですか？`,"feedback.placeholder.other":`メッセージ…`,"feedback.email":`メールアドレス`,"feedback.emailHint":`返信のため（および不正利用防止のため）必須です。それ以外には使用しません。`,"feedback.send":`送信`,"feedback.sentWith":`バージョン（{version}）で送信しました`,"feedback.sentWithName":`バージョン（{version}）とニックネーム（{name}）で送信しました`,"feedback.sentTitle":`ありがとうございます！`,"feedback.sentBody":`メッセージはチームに届きました。確認メールを {email} に送信しています。`,"feedback.err.email":`有効なメールアドレスを入力してください`,"feedback.err.message":`数文でよいので入力してください`,"feedback.err.rate":`メッセージの送信が多すぎます。しばらくしてからもう一度お試しください。`,"feedback.err.unreachable":`現在、このサーバーから Harness Maxxing チームに接続できません。しばらくしてからもう一度お試しください。`,"feedback.zone":`範囲をキャプチャ`,"feedback.zoneBlur":`データを隠す（プレゼンテーションモード）`,"feedback.zoneHint":`送信したい画面の範囲をドラッグ · Enter = 画面全体 · Esc = キャンセル`,"feedback.zoneHintTouch":`送信したい画面の範囲をドラッグしてください`,"feedback.zoneWhole":`画面全体`,"feedback.zoneTaking":`キャプチャ中…`,"feedback.zoneAlt":`メッセージと一緒に送信するスクリーンショット`,"feedback.zoneRedo":`撮り直す`,"feedback.zoneRemove":`削除`,"feedback.zoneFailed":`スクリーンショットを撮影できませんでした。もっと小さい範囲でお試しください。`,"feedback.err.image":`スクリーンショットが受け付けられませんでした。削除するか、もっと小さい範囲をキャプチャしてください。`,"feedback.err.offline":`このサーバーは Harness Maxxing クラウドに一切接続しない設定になっています。`};export{e as default};